example_solution:
class SquareRoot {

    static Integer squareRoot(Integer radicand) {
        Integer result = 0

        while (result ** 2 != radicand) {
            result += 1
        }

        result
    }

}

test_code:
import spock.lang.*

class SquareRootSpec extends Specification {

    @Unroll
    def "root of #radicand"() {
        expect:
        SquareRoot.squareRoot(radicand) == expected

        where:
        radicand    || expected
        1           || 1
        4           || 2
        25          || 5
        81          || 9
        196         || 14
        65025       || 255
    }
}
